:root{--bg:#f7f8fa;--paper:#fff;--soft:#f1f3f5;--line:#e0e4e9;--txt:#252a30;--muted:#707983;--accent:#8b6f3d;--accent-soft:#f5f0e8;--green:#3c8b5b;--blue:#4b78b8;--red:#b34e4e;--shadow:0 8px 28px rgba(32,36,42,.05);--max:920px}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--txt);font-family:Inter,system-ui,-apple-system,"Segoe UI",Arial,sans-serif;font-size:17px;font-weight:400;line-height:1.72;-webkit-font-smoothing:antialiased}button,input,select,textarea{font:inherit;font-size:16px;font-weight:400}.wrap{width:min(var(--max),calc(100% - 28px));margin:auto}.top{position:sticky;top:0;z-index:20;background:rgba(255,255,255,.95);backdrop-filter:blur(10px);border-bottom:1px solid var(--line)}.topin{min-height:66px;display:flex;align-items:center;justify-content:space-between;gap:14px}.brand{font-weight:500;font-size:17px;letter-spacing:.04em}.brand span{color:var(--accent);font-weight:400}.top a{color:var(--accent);text-decoration:none;font-size:15px}.hero{padding:42px 0 14px}.eyebrow{font-size:12px;color:var(--accent);font-weight:500;letter-spacing:.08em;text-transform:uppercase}.hero h1{font-size:clamp(36px,6vw,52px);font-weight:400;letter-spacing:-.035em;line-height:1.08;margin:7px 0 13px}.hero p{color:var(--muted);max-width:720px;margin:0;font-size:18px}.guide{margin:18px 0 28px;background:var(--paper);border:1px solid var(--line);border-radius:20px;padding:28px;box-shadow:var(--shadow)}.step-line{display:flex;justify-content:space-between;gap:16px;align-items:center;margin-bottom:12px;color:var(--muted);font-size:14px}.step-line span:last-child{white-space:nowrap}.guide h2{font-size:30px;font-weight:500;line-height:1.25;letter-spacing:-.025em;margin:4px 0 8px}.guide .why{color:var(--muted);font-size:16px;margin:0 0 20px}.guide-question{background:var(--accent-soft);border-radius:12px;padding:16px 18px;margin:16px 0 18px;font-size:18px}.quick-field label{display:block;font-size:14px;color:var(--muted);margin-bottom:7px}.quick-field textarea{width:100%;min-height:155px;resize:vertical;background:#fff;color:var(--txt);border:1px solid var(--line);border-radius:10px;padding:14px;line-height:1.65}.quick-actions{display:flex;gap:9px;flex-wrap:wrap;margin-top:14px;align-items:center}.quick-meta{font-size:13px;color:var(--muted);margin-right:auto}.btn{border:1px solid var(--line);background:var(--paper);color:var(--txt);border-radius:9px;padding:10px 14px;font-weight:500;cursor:pointer}.btn:hover{background:var(--soft)}.btn.primary{background:var(--accent);border-color:var(--accent);color:#fff}.btn.subtle{background:transparent}.btn.danger{color:var(--red);border-color:#e8caca}.btn.small{padding:7px 10px;font-size:13px}.errorbox{display:none;padding:14px;border-radius:10px;background:#fff0f0;border:1px solid #efc5c5;color:#8f3939;margin:12px 0}.advanced{margin:22px 0 34px}.advanced>summary{cursor:pointer;list-style:none;text-align:center;color:var(--accent);font-size:16px;padding:12px}.advanced>summary::-webkit-details-marker{display:none}.advanced>summary:after{content:'  ↓'}.advanced[open]>summary:after{content:'  ↑'}.advanced-content{padding-top:8px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:12px 0 22px}.stat{background:var(--paper);border:1px solid var(--line);border-radius:12px;padding:14px}.stat span{display:block;color:var(--muted);font-size:13px}.stat strong{font-size:25px;font-weight:500}.toolbar{display:flex;flex-wrap:wrap;gap:8px;margin:10px 0 24px}.loadbox{padding:17px;border:1px dashed var(--line);border-radius:10px;color:var(--muted);background:var(--paper);font-size:16px}.section{margin:28px 0}.section-head{margin-bottom:12px}.section-head h2{margin:3px 0 0;font-size:26px;font-weight:500}.section-head p{margin:4px 0;color:var(--muted);font-size:16px}.phase{background:var(--paper);border:1px solid var(--line);border-radius:14px;margin:10px 0;overflow:hidden}.phase>summary{cursor:pointer;list-style:none;padding:17px}.phase>summary::-webkit-details-marker{display:none}.phase-title{display:flex;gap:13px;align-items:center}.phase-title strong{font-weight:500;font-size:18px}.phase-title small{display:block;color:var(--muted);font-size:14px}.num{width:34px;height:34px;border-radius:50%;display:grid;place-items:center;background:var(--accent-soft);color:var(--accent);font-weight:500}.tasks{padding:0 12px 12px}.task{background:#fbfcfd;border:1px solid var(--line);border-radius:10px;margin:9px 0;overflow:hidden}.task>summary{cursor:pointer;list-style:none;padding:15px}.task>summary::-webkit-details-marker{display:none}.task-head{display:flex;gap:11px;align-items:center}.task-head b{font-weight:500;font-size:17px}.dot{width:9px;height:9px;border-radius:50%;background:#9ca5af}.task[data-status=done] .dot{background:var(--green)}.task[data-status=doing] .dot{background:var(--blue)}.task[data-status=blocked] .dot{background:var(--red)}.task-head span{margin-left:auto;color:var(--muted);font-size:13px}.task-body{border-top:1px solid var(--line);padding:17px}.task-body p{color:var(--muted);font-size:16px}.question{background:var(--accent-soft);border-left:3px solid var(--accent);padding:14px;margin:14px 0;font-size:16px}.question b,.field label,.idea strong,.decision b,.history-item strong,.history-diff b{font-weight:500}.field{margin:14px 0}.field label{display:block;font-size:14px;margin-bottom:6px}.field textarea,.field select,.field input,.form-row input,.form-row select{width:100%;background:#fff;color:var(--txt);border:1px solid var(--line);border-radius:8px;padding:11px 12px}.field textarea{min-height:118px;resize:vertical;line-height:1.6}.row{display:grid;grid-template-columns:180px 1fr;gap:12px}.save{display:flex;justify-content:flex-end;gap:10px;align-items:center}.saved{font-size:13px;color:var(--muted)}.panel{background:var(--paper);border:1px solid var(--line);border-radius:14px;padding:19px;box-shadow:var(--shadow)}.collapse{background:transparent;border:0;box-shadow:none}.collapse>summary{cursor:pointer;list-style:none;padding:15px 0;font-weight:500;font-size:19px}.collapse>summary::-webkit-details-marker{display:none}.idea-form{display:grid;grid-template-columns:1fr auto;gap:8px}.idea-form textarea{grid-column:1/-1;min-height:86px;resize:vertical;background:#fff;border:1px solid var(--line);border-radius:8px;padding:11px 12px;line-height:1.6}.idea-form input{background:#fff;border:1px solid var(--line);border-radius:8px;padding:11px 12px}.idea-list{display:grid;gap:9px;margin-top:15px}.idea{border:1px solid var(--line);border-radius:10px;padding:14px;background:#fbfcfd}.idea-head{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.idea p{margin:6px 0;color:var(--muted);white-space:pre-wrap;font-size:16px}.idea small,.history-item small{color:var(--muted);font-size:13px}.idea-actions{display:flex;gap:6px}.form-row{display:grid;grid-template-columns:1fr 160px auto;gap:8px}.decision{padding:11px 0;border-top:1px solid var(--line);font-size:16px}.history-controls{display:flex;gap:8px;flex-wrap:wrap}.history-filter{background:#fff;border:1px solid var(--line);border-radius:8px;padding:10px}.history-list{display:grid;gap:8px;margin-top:13px}.history-item{border:1px solid var(--line);border-radius:10px;padding:14px;display:grid;grid-template-columns:1fr auto;gap:10px;background:#fbfcfd}.history-diff{margin-top:7px;color:#555e68;font-size:14px;line-height:1.6;white-space:pre-wrap}.login-shell{min-height:100vh;display:grid;place-items:center;padding:18px}.login{width:min(430px,100%);background:#fff;border:1px solid var(--line);border-radius:16px;padding:26px;box-shadow:var(--shadow)}.login h1{font-weight:500;font-size:34px}.login p{color:var(--muted)}.login label{font-size:14px;font-weight:500}.login input{width:100%;padding:12px;background:#fff;border:1px solid var(--line);border-radius:8px;margin:5px 0 10px}.footer{padding:34px 0;color:var(--muted);font-size:13px}.toast{position:fixed;right:16px;bottom:16px;background:#fff;border:1px solid var(--line);padding:11px 14px;border-radius:9px;box-shadow:var(--shadow);display:none;font-size:14px}@media(max-width:720px){body{font-size:16px}.guide{padding:20px}.guide h2{font-size:25px}.step-line{align-items:flex-start;flex-direction:column;gap:2px}.stats{grid-template-columns:1fr 1fr}.row,.form-row,.idea-form,.history-item{grid-template-columns:1fr}.idea-form textarea{grid-column:auto}.idea-head{flex-direction:column}.save{align-items:flex-end;flex-direction:column}.quick-actions{align-items:stretch;flex-direction:column}.quick-meta{margin:0}.btn{width:100%}}
</style>
